"""Emit KiCad 10 hierarchical projects from FabricAST (GATE-L4-FABRIC).

GENERATED trees under kicad/{bringup_2x2,driver_64x64}/ — do not hand-edit;
fix topology in generators/ and re-run the CLI.
"""

from __future__ import annotations

import json
import re
from pathlib import Path

from generators.mce_array import FabricAST, OctalTile, build_fabric
from generators.sexpr import KICAD_SCH_VERSION, det_uuid, write_sexpr

ROOT = Path(__file__).resolve().parents[1]
KICAD_ROOT = ROOT / "kicad"

GENERATED_BANNER = (
    "GENERATED by generators/ — do not hand-edit; "
    "uv run python -m generators.cli --n {n}"
)

# KiCad schematic connection grid (50 mil).
GRID_MM = 1.27


def snap(v: float) -> float:
    """Snap to the schematic connection grid (avoids endpoint_off_grid)."""
    return round(v / GRID_MM) * GRID_MM


def _effects(size: float = 1.27, hide: bool = False, justify: str | None = None) -> list:
    eff: list = ["effects", ["font", ["size", size, size]]]
    if justify:
        eff.append(["justify", justify])
    if hide:
        eff.append(["hide", True])
    return eff


def _property(name: str, value: str, x: float, y: float, *, hide: bool = False) -> list:
    return [
        "property",
        name,
        value,
        ["at", x, y, 0],
        _effects(hide=hide),
    ]


def _lib_r() -> list:
    """Embedded resistor — CMR: prefix avoids Device library mismatch warnings."""
    return [
        "symbol",
        "CMR:R",
        ["pin_numbers", ["hide", True]],
        ["pin_names", ["offset", 0]],
        ["exclude_from_sim", False],
        ["in_bom", True],
        ["on_board", True],
        _property("Reference", "R", 2.032, 0),
        _property("Value", "R", 0, 0),
        _property("Footprint", "", -1.778, 0, hide=True),
        _property("Datasheet", "~", 0, 0, hide=True),
        _property("Description", "Resistor", 0, 0, hide=True),
        [
            "symbol",
            "R_0_1",
            [
                "rectangle",
                ["start", -1.016, -2.54],
                ["end", 1.016, 2.54],
                ["stroke", ["width", 0.254], ["type", "default"]],
                ["fill", ["type", "none"]],
            ],
        ],
        [
            "symbol",
            "R_1_1",
            [
                "pin",
                "passive",
                "line",
                ["at", 0, 3.81, 270],
                ["length", 1.27],
                ["name", "~", _effects()],
                ["number", "1", _effects()],
            ],
            [
                "pin",
                "passive",
                "line",
                ["at", 0, -3.81, 90],
                ["length", 1.27],
                ["name", "~", _effects()],
                ["number", "2", _effects()],
            ],
        ],
    ]


def _lib_stub() -> list:
    """One-pin passive stub — terminates labels/ports without NC-on-connected-pin."""
    return [
        "symbol",
        "CMR:Stub",
        ["pin_numbers", ["hide", True]],
        ["pin_names", ["offset", 0], ["hide", True]],
        ["exclude_from_sim", True],
        ["in_bom", False],
        ["on_board", False],
        _property("Reference", "TP", 1.27, 0),
        _property("Value", "Stub", 0, 0),
        _property("Footprint", "", 0, 0, hide=True),
        _property("Datasheet", "~", 0, 0, hide=True),
        _property("Description", "ERC stub terminator", 0, 0, hide=True),
        [
            "symbol",
            "Stub_0_1",
            [
                "circle",
                ["center", 0, 0],
                ["radius", 0.635],
                ["stroke", ["width", 0.254], ["type", "default"]],
                ["fill", ["type", "none"]],
            ],
        ],
        [
            "symbol",
            "Stub_1_1",
            [
                "pin",
                "passive",
                "line",
                ["at", -2.54, 0, 0],
                ["length", 2.54],
                ["name", "~", _effects()],
                ["number", "1", _effects()],
            ],
        ],
    ]


