def _sheet_base(key: str, title: str, n: int, lib_symbols: list | None = None) -> tuple[list, str]:
    suuid = det_uuid(f"sheet/{key}")
    body: list = [
        "kicad_sch",
        ["version", KICAD_SCH_VERSION],
        ["generator", "core-memory-redux"],
        ["generator_version", "10.0"],
        ["uuid", suuid],
        ["paper", "A3"],
        [
            "title_block",
            ["title", title],
            ["comment", 1, GENERATED_BANNER.format(n=n)],
        ],
        ["lib_symbols", *(lib_symbols or [])],
    ]
    return body, suuid


def emit_steer_tile(fabric: FabricAST, tile: OctalTile, out_dir: Path) -> str:
    """Emit one octal steer sheet with SS14 diodes for populated lines."""
    key = tile.sheet_name
    body, suuid = _sheet_base(key, key, fabric.n, [_lib_diode(), _lib_r(), _lib_stub()])
    items: list = [
        _text(f"{key}/banner", f"REQ-HIER-OCTAL {key} pins={len(tile.pins)}", 10, 10),
        _text(f"{key}/lines", f"lines={list(tile.lines)}", 10, 15),
    ]
    # Hierarchical pins along left edge
    y = 25.0
    for pin in tile.pins:
        items.extend(_hier_port(pin, 20.0, y, suuid))
        y += 2.54
        if y > 180:
            y = 25.0
    # Diodes: anode label — diode — cathode label
    dx, dy = 120.0, 25.0
    for i, edge in enumerate(tile.diodes):
        ref = f"D{tile.axis}{tile.group}_{i}"
        items.append(_place_diode(f"{key}/{ref}", ref, dx, dy, suuid))
        items.append(_global_label(edge.anode, dx + 5.08, dy, 0))
        items.append(_global_label(edge.cathode, dx - 5.08, dy, 180))
        items.append(_wire(f"{key}/{ref}/a", dx + 3.81, dy, dx + 5.08, dy))
        items.append(_wire(f"{key}/{ref}/k", dx - 3.81, dy, dx - 5.08, dy))
        dy += 7.62
        if dy > 180:
            dy = 25.0
            dx += 40.0
    body.extend(items)
    body.append(["sheet_instances", ["path", "/", ["page", "1"]]])
    path = out_dir / f"{key}.kicad_sch"
    write_sexpr(path, body)
    return key


def emit_decode_block(fabric: FabricAST, out_dir: Path) -> str:
    key = "decode_block"
    body, suuid = _sheet_base(
        key,
        "decode_block (74AHC138 HS + 74AHC238 LS)",
        fabric.n,
        [_lib_r(), _lib_stub()],
    )
    items: list = [
        _text(f"{key}/mpn", "MPN: 74AHC138 + 74AHC238 (lib_id 74xx; Value=AHC)", 10, 10),
        _text(f"{key}/failsafe", "Fail-safe: FWD_EN_n/REV_EN_n pull-up; DEC_EN pull-down", 10, 15),
    ]
    pins = [
        ("ADDR_NH0", "input"),
        ("ADDR_NH1", "input"),
        ("ADDR_NH2", "input"),
        ("ADDR_NL0", "input"),
        ("ADDR_NL1", "input"),
        ("ADDR_NL2", "input"),
        ("BANK_EN", "input"),
        ("DEC_EN", "input"),
    ]
    for i in range(8):
        pins.append((f"N_HS{i}_n", "output"))
    for i in range(8):
        pins.append((f"N_LS{i}_en", "output"))
    y = 25.0
    for name, shape in pins:
        items.extend(_hier_port(name, 25.0, y, suuid, shape))
        y += 2.54
    # Pull resistors on bank enables (tune/fail-safe presence)
    items.append(_place_r(f"{key}/Rpu", "Rpu_BANK", "10k", 100, 40, suuid))
    items.extend(_global_label_terminated("BANK_EN", 100, 40 - 3.81, suuid, 90))
    items.extend(_global_label_terminated("+3V3", 100, 40 + 3.81, suuid, 270))
    items.append(_place_r(f"{key}/Rpd", "Rpd_DEC", "10k", 120, 40, suuid))
    items.extend(_global_label_terminated("DEC_EN", 120, 40 - 3.81, suuid, 90))
    items.append(_global_label("AGND", 120, 40 + 3.81, 270))
    body.extend(items)
    body.append(["sheet_instances", ["path", "/", ["page", "1"]]])
    write_sexpr(out_dir / f"{key}.kicad_sch", body)
    return key


def emit_dmos(fabric: FabricAST, out_dir: Path, kind: str) -> str:
    """kind: hs -> TBD62783, ls -> TBD62083."""
    key = f"dmos_{kind}_array"
    mpn = "TBD62783" if kind == "hs" else "TBD62083"
    body, suuid = _sheet_base(key, f"{key} ({mpn})", fabric.n, [_lib_r(), _lib_stub()])
    items: list = [
        _text(f"{key}/mpn", f"REQ-DRV-DMOS MPN={mpn} — pin-faithful sheet; not transistor-level", 10, 10),
        *_hier_port("VDRIVE", 25, 25, suuid, "input"),
        *_hier_port("CCS_RET", 25, 30, suuid, "output"),
    ]
    y = 40.0
    for i in range(8):
        if kind == "hs":
            items.extend(_hier_port(f"IN{i}_n", 25, y, suuid, "input"))
            items.extend(_hier_port(f"OUT{i}", 80, y, suuid, "output"))
        else:
            items.extend(_hier_port(f"IN{i}_en", 25, y, suuid, "input"))
            items.extend(_hier_port(f"OUT{i}", 80, y, suuid, "output"))
        y += 2.54
    body.extend(items)
    body.append(["sheet_instances", ["path", "/", ["page", "1"]]])
    write_sexpr(out_dir / f"{key}.kicad_sch", body)
    return key


