def emit_magnetic(fabric: FabricAST, out_dir: Path) -> str:
    key = "magnetic_plane"
    body, suuid = _sheet_base(
        key,
        f"magnetic_plane n={fabric.n} (bus/connector/fold interface)",
        fabric.n,
        [_lib_r(), _lib_stub()],
    )
    items: list = [
        _text(
            f"{key}/note",
            "Interface only — no 4096 core symbols. Weave proven by AST + L3 SIL.",
            10,
            10,
        ),
        _text(f"{key}/fold", "REQ-ICD-FOLD: YA66=YB65=SENSE_FOLD; 10k soft bias to AGND", 10, 15),
    ]
    y = 30.0
    for bus, nets in fabric.plane_buses.items():
        items.append(_text(f"{key}/bus/{bus}", f"{bus}[0..{fabric.n - 1}]", 20, y))
        # Expose endpoints + a few samples as hierarchical labels (full bus on root labels)
        for net in (nets[0], nets[-1]):
            items.extend(_hier_port(net, 40, y, suuid, "bidirectional"))
            y += 2.54
        y += 2.54
    for name in ("YA65", "YB66", "YA66", "YB65", "SENSE_FOLD"):
        items.extend(_hier_port(name, 40, y, suuid, "bidirectional"))
        y += 2.54
    # Soft bias + REQ-ICD-FOLD short: YA66 and YB65 share net SENSE_FOLD
    items.append(_place_r(f"{key}/Rfold", "Rfold", "10k", 120, 50, suuid))
    items.append(_global_label("SENSE_FOLD", 120, 50 - 3.81, 90))
    items.append(_global_label("AGND", 120, 50 + 3.81, 270))
    # Alias note only — do not place a second dangling SENSE_FOLD global.
    items.append(_text(f"{key}/alias", "YA66 ≡ YB65 ≡ SENSE_FOLD (external jumper)", 140, 40))
    body.extend(items)
    body.append(["sheet_instances", ["path", "/", ["page", "1"]]])
    write_sexpr(out_dir / f"{key}.kicad_sch", body)
    return key


def _sheet_instance(
    key: str,
    fname: str,
    x: float,
    y: float,
    w: float,
    pin_names: list[str],
) -> tuple[list, list]:
    """Hierarchical sheet box on root.

    Returns (sheet_node, tie_items) where tie_items wire each sheet pin to a
    same-named global label so ERC sees a connection.
    """
    x, y, w = snap(x), snap(y), snap(w)
    pins = []
    ties: list = []
    py = GRID_MM * 2
    for pn in pin_names:
        # KiCad: (pin "NAME" <electrical> (at x y rot) (uuid ...) (effects ...))
        pins.append(
            [
                "pin",
                pn,
                "bidirectional",
                ["at", x, y + py, 180],
                ["uuid", det_uuid(f"sheetpin/{key}/{pn}")],
                _effects(justify="left"),
            ]
        )
        ties.extend(_sheet_pin_nc(f"{key}/{pn}", x, y + py, det_uuid("sheet/driver")))
        py = snap(py + GRID_MM * 2)
    h = snap(max(25.4, py + GRID_MM * 2))
    sheet = [
        "sheet",
        ["at", x, y],
        ["size", w, h],
        ["exclude_from_sim", False],
        ["in_bom", True],
        ["on_board", True],
        ["dnp", False],
        ["fields_autoplaced", False],
        ["stroke", ["width", 0.1524], ["type", "solid"]],
        ["fill", ["type", "none"]],
        ["uuid", det_uuid(f"sheetbox/{key}")],
        [
            "property",
            "Sheetname",
            key,
            ["at", x, y - 1.27, 0],
            _effects(),
        ],
        [
            "property",
            "Sheetfile",
            fname,
            ["at", x, y + h + 1.27, 0],
            _effects(),
        ],
        *pins,
    ]
    return sheet, ties


def emit_root(fabric: FabricAST, out_dir: Path, sheet_files: dict[str, str]) -> None:
    key = "driver"
    body, _suuid = _sheet_base(
        key,
        f"{fabric.project_name()} root n={fabric.n}",
        fabric.n,
        [_lib_stub()],
    )
    items: list = [
        _text(
            f"{key}/tune",
            "Tune points: CCS_*_TRIM, VDRIVE, INH_POL_SEL, PIO_STROBE "
            "(design_choices bring-up; not ICD freeze)",
            10,
            8,
        ),
    ]

    # Pin lists must match hierarchical_label sets on child sheets (ERC hier match).
    magnetic_pins: list[str] = []
    for _bus, nets in fabric.plane_buses.items():
        magnetic_pins.extend((nets[0], nets[-1]))
    magnetic_pins.extend(["YA65", "YB66", "YA66", "YB65", "SENSE_FOLD"])

    decode_pins = [
        "ADDR_NH0",
        "ADDR_NH1",
        "ADDR_NH2",
        "ADDR_NL0",
        "ADDR_NL1",
        "ADDR_NL2",
        "BANK_EN",
        "DEC_EN",
        *[f"N_HS{i}_n" for i in range(8)],
        *[f"N_LS{i}_en" for i in range(8)],
    ]
    dmos_hs_pins = ["VDRIVE", "CCS_RET", *[f"IN{i}_n" for i in range(8)], *[f"OUT{i}" for i in range(8)]]
    dmos_ls_pins = ["VDRIVE", "CCS_RET", *[f"IN{i}_en" for i in range(8)], *[f"OUT{i}" for i in range(8)]]

    layout: list[tuple[str, str, list[str]]] = [
        ("magnetic_plane", sheet_files["magnetic_plane"], magnetic_pins),
        (
            "sense_front_end",
            sheet_files["sense_front_end"],
            ["YA65", "YB66", "DOUT", "SENSE_STROBE", "INH_POL_SEL", "PIO_STROBE"],
        ),
        ("ccs_channel", sheet_files["ccs_channel"], ["CCS_RET", "ISENSE", "VDRIVE"]),
        ("decode_block", sheet_files["decode_block"], decode_pins),
        ("dmos_hs_array", sheet_files["dmos_hs_array"], dmos_hs_pins),
        ("dmos_ls_array", sheet_files["dmos_ls_array"], dmos_ls_pins),
    ]

    x, y = snap(101.6), snap(25.4)
    for name, fname, pins in layout:
        sheet, ties = _sheet_instance(name, fname, x, y, snap(45.72), pins)
        items.append(sheet)
        items.extend(ties)
        x = snap(x + 55.88)
        if x > 355.6:
            x = snap(101.6)
            y = snap(y + 121.92)

    x, y = snap(101.6), snap(y + 129.54)
    for tile in fabric.tiles:
        fname = sheet_files[tile.sheet_name]
        sheet, ties = _sheet_instance(
            tile.sheet_name,
            fname,
            x,
            y,
            snap(40.64),
            list(tile.pins),
        )
        items.append(sheet)
        items.extend(ties)
        x = snap(x + 50.8)
        if x > 381.0:
            x = snap(101.6)
            y = snap(y + 111.76)

    dy = snap(y + 121.92)
    for call in fabric.decode_calls:
        items.append(
            _text(
                f"{key}/{call.instance}",
                f"{call.instance} -> decode_block.kicad_sch ({call.axis} {call.direction})",
                snap(101.6),
                dy,
            )
        )
        dy = snap(dy + 5.08)

    body.extend(items)
    body.append(["sheet_instances", ["path", "/", ["page", "1"]]])
    write_sexpr(out_dir / "driver.kicad_sch", body)



def emit_pro(fabric: FabricAST, out_dir: Path) -> None:
    """Minimal KiCad project file."""
    name = fabric.project_name()
    root_uuid = det_uuid("sheet/driver")
    pro = {
        "board": {
            "design_settings": {
                "defaults": {},
                "diff_pair_dimensions": [],
                "drc_exclusions": [],
                "rules": {},
                "track_widths": [],
                "via_dimensions": [],
            }
        },
        "boards": [],
        "libraries": {"pinned_footprint_libs": [], "pinned_symbol_libs": []},
        "meta": {"filename": f"{name}.kicad_pro", "version": 3},
        "net_settings": {"classes": [], "meta": {"version": 0}},
        "schematic": {
            "meta": {"version": 1},
            "page_layout_descr_file": "",
            "plot_directory": "",
        },
        "sheets": [[root_uuid, "Root"]],
        "text_variables": {},
    }
    (out_dir / f"{name}.kicad_pro").write_text(
        json.dumps(pro, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )


def emit_project(n: int, kicad_root: Path | None = None) -> Path:
    fabric = build_fabric(n)
    root = kicad_root or KICAD_ROOT
    out_dir = root / fabric.project_name()
    if out_dir.exists():
        # Idempotent clean of generated sch/pro/json only
        for p in out_dir.glob("*.kicad_sch"):
            p.unlink()
        for p in out_dir.glob("*.kicad_pro"):
            p.unlink()
        for p in out_dir.glob("fabric_manifest.json"):
            p.unlink()
    out_dir.mkdir(parents=True, exist_ok=True)

    sheet_files: dict[str, str] = {}
    for tile in fabric.tiles:
        name = emit_steer_tile(fabric, tile, out_dir)
        sheet_files[name] = f"{name}.kicad_sch"
    sheet_files["decode_block"] = f"{emit_decode_block(fabric, out_dir)}.kicad_sch"
    sheet_files["dmos_hs_array"] = f"{emit_dmos(fabric, out_dir, 'hs')}.kicad_sch"
    sheet_files["dmos_ls_array"] = f"{emit_dmos(fabric, out_dir, 'ls')}.kicad_sch"
    sheet_files["ccs_channel"] = f"{emit_ccs(fabric, out_dir)}.kicad_sch"
    sheet_files["sense_front_end"] = f"{emit_sense(fabric, out_dir)}.kicad_sch"
    sheet_files["magnetic_plane"] = f"{emit_magnetic(fabric, out_dir)}.kicad_sch"
    emit_root(fabric, out_dir, sheet_files)
    emit_pro(fabric, out_dir)

    manifest = fabric.summary()
    manifest["sheets"] = sorted(sheet_files.keys())
    manifest["root"] = "driver.kicad_sch"
    (out_dir / "fabric_manifest.json").write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )
    (out_dir / "README.md").write_text(
        f"# {fabric.project_name()} (GENERATED)\n\n"
        f"{GENERATED_BANNER.format(n=n)}\n\n"
        f"- Root: `driver.kicad_sch`\n"
        f"- Manifest: `fabric_manifest.json`\n"
        f"- Gate: **GATE-L4-FABRIC** / **REQ-HIER-OCTAL**\n",
        encoding="utf-8",
    )
    return out_dir
